<?php
require_once __DIR__.'/app/layout.php';require_login();
$id=int_param($_GET['id']??null);if(!$id){http_response_code(404);exit('Prediction not found.');}
$p=query_one('SELECT pr.PredictionID,pr.PatientID,pr.ModelVersion,pr.CreatedAt,pr.CreatedBy,p.Name,p.TCGAPatientID FROM Prediction pr JOIN Patient p ON p.PatientID=pr.PatientID WHERE pr.PredictionID=?',[$id]);
if(!$p || !can_view_patient((int)$p['PatientID'])){http_response_code(404);exit('Prediction not available.');}
$scores=query_rows('SELECT ct.StudyCode,ct.DiagnosisLabel,ps.Score FROM PredictionScore ps JOIN CancerType ct ON ct.CancerTypeID=ps.CancerTypeID WHERE ps.PredictionID=? ORDER BY ps.Score DESC',[$id]);
$feedback=query_rows('SELECT f.IsAccurate,f.Comments,f.CreatedAt,u.Name FROM Feedback f JOIN AppUser u ON u.UserID=f.UserID WHERE f.PredictionID=? ORDER BY f.FeedbackID DESC LIMIT 20',[$id]);
$linkedMutations=(int)query_value('SELECT COUNT(*) FROM PredictionMutation WHERE PredictionID=?',[$id]);
audit('VIEW_PREDICTION','Prediction',(string)$id);
start_page('Prediction #'.$id,'predictions.php','Previously stored model outputs and feedback.','MODEL HISTORY');
?><div class="backlink"><a href="predictions.php">← Back to prediction history</a></div><section class="panel"><div class="panel-title"><div><h2>Prediction record</h2><p>Patient: <a href="patient.php?id=<?=$p['PatientID']?>"><?=h($p['Name'])?></a> · Model: <?=h($p['ModelVersion'])?> · <?=h($p['CreatedAt'])?> · Based on <?=number_format($linkedMutations)?> linked mutation records</p></div></div><?php if($scores):?><div class="ranked-bars"><?php foreach($scores as $s):?><div class="rank-row"><span><?=h(strtoupper($s['StudyCode']))?></span><div class="rank-track"><i style="width:<?=round((float)$s['Score']*100,1)?>%"></i></div><b><?=number_format((float)$s['Score']*100,1)?>%</b></div><?php endforeach;?></div><?php else:?><?php empty_state('No scores saved','The prediction record has no associated cancer-type scores.');?><?php endif;?><p class="small-help">Model scores are experimental and are not clinical probabilities without appropriate validation and calibration.</p></section>
<section class="panel"><div class="panel-title"><div><h2>Feedback</h2><p>Feedback is stored against the specific prediction ID.</p></div></div><?php foreach($feedback as $f):?><div class="feedback-card"><b><?=h($f['Name'])?></b><span class="chip informative"><?= $f['IsAccurate']===null?'Uncertain':($f['IsAccurate']?'Accurate':'Not accurate') ?></span><p><?=display($f['Comments'])?></p><small><?=h($f['CreatedAt'])?></small></div><?php endforeach;?><?php if(!$feedback):?><p class="muted">No feedback has been recorded.</p><?php endif;?><form method="post" action="feedback.php" class="feedback-form"><?=csrf_field()?><input type="hidden" name="prediction_id" value="<?=$id?>"><label for="accuracy">Prediction assessment</label><select id="accuracy" name="accuracy" required><option value="">Select an assessment</option><option value="1">Accurate</option><option value="0">Not accurate</option><option value="unknown">Cannot assess</option></select><label for="comments">Comments (optional)</label><textarea id="comments" name="comments" maxlength="1500" rows="3" placeholder="Explain the assessment or note limitations"></textarea><button type="submit" class="button primary">Save feedback</button></form></section>
<?php end_page();
